export const NETWORKS=['ZES','Lumicle','Astor','WAT','Trugo'];
export const DEFAULTS={origin:'Zekeriyaköy, İstanbul',destination:'Urla Belediyesi, İzmir',battery:100,chargeTarget:80,reserve:20,buffer:5,speed:130,people:2,personWeight:75,luggage:20,payloadOverride:'',capacity:60.48,curbMass:1750,maxDcPower:95,maxAcPower:11,dcConnector:'CCS2',acConnector:'Type2',baseConsumption:23,headwind:0,temperature:20,priority:'balanced',fastOnly:true,networks:NETWORKS,tariffs:{ZES:15,Lumicle:15,Astor:15,WAT:15,Trugo:15},mode:'sample'};
export function payload(s){return s.payloadOverride!==''?Number(s.payloadOverride):s.people*s.personWeight+s.luggage;}
export function validate(s){for(const key of ['battery','reserve','buffer','speed','people','personWeight','luggage','capacity','baseConsumption','headwind','temperature'])if(!Number.isFinite(Number(s[key])))throw Error('Please enter valid numbers for all vehicle settings.');if(s.battery<=s.reserve+s.buffer)throw Error('Starting battery must be higher than your reserve plus safety buffer.');if(s.battery>100||s.reserve<5||s.reserve+s.buffer>=100||s.capacity<=0||s.baseConsumption<=0||s.speed<60||s.speed>140)throw Error('Check your battery, reserve, speed, and consumption settings.');if(s.people<1||s.people>5||s.personWeight<0||s.luggage<0||!Number.isFinite(payload(s))||payload(s)<0)throw Error('Enter 1–5 occupants and a valid, non-negative payload.');if(!s.networks.length)throw Error('Choose at least one charging network.');for(const n of s.networks)if(!Number.isFinite(Number(s.tariffs[n]))||Number(s.tariffs[n])<=0)throw Error('Enter a positive price assumption for each selected network.');}
// Calibrated baseline is 130 km/h on level road, 20°C, 75 kg driver.
// Splits the baseline into 65% aerodynamic, 30% rolling, 5% auxiliary load.
export function consumption(s){const mass=(s.curbMass??1750)+payload(s),refMass=(s.curbMass??1750)+75;const air=Math.max(0,s.speed+s.headwind)/130;return s.baseConsumption*(.65*air*air+.30*mass/refMass+.05*130/s.speed)+Math.max(0,15-s.temperature)*.09;}
export function segmentEnergy(km,rise,s){const rolling=km*consumption(s)/100;const potential=((s.curbMass??1750)+payload(s))*9.81*rise/3600000;return Math.max(0,rolling+(rise>=0?potential/.88:potential*.60));}
export function chargeMinutes(from,to,power,s,kind=power<=22?'ac':'dc'){let mins=0;for(let x=from;x<to;x+=.25){const step=Math.min(.25,to-x);const acceptance=(s.maxDcPower??95)*(x<60?1:x<80?65/95:x<90?43/95:25/95);const limit=kind==='ac'?(s.maxAcPower??11):acceptance;if(limit<=0||power<=0)return Infinity;mins+=step/100*s.capacity/Math.min(power,limit)/.92*60;}return mins;}
export const SAMPLE={distance:560,duration:330,origin:DEFAULTS.origin,destination:DEFAULTS.destination,source:'sample',profile:[{km:0,elevation:100},{km:75,elevation:140},{km:145,elevation:20},{km:185,elevation:70},{km:220,elevation:300},{km:252,elevation:80},{km:295,elevation:100},{km:345,elevation:160},{km:380,elevation:410},{km:437,elevation:100},{km:480,elevation:300},{km:520,elevation:60},{km:560,elevation:20}],stations:[{id:'gemlik-zes',name:'Oksijen O68 · Gemlik',network:'ZES',km:185,power:180,detour:0},{id:'gemlik-lumicle',name:'Oksijen O68 · Gemlik',network:'Lumicle',km:186,power:180,detour:0},{id:'bursa-wat',name:'Oksijen O86 · Bursa',network:'WAT',km:203,power:120,detour:0},{id:'karacabey-wat',name:'Oksijen O122 · Karacabey',network:'WAT',km:239,power:120,detour:0},{id:'karacabey-zes',name:'Oksijen O135 · Karacabey',network:'ZES',km:252,power:180,detour:0},{id:'susurluk-zes',name:'Oksijen O178 · Susurluk',network:'ZES',km:295,power:180,detour:0},{id:'balikesir-trugo',name:'Oksijen O228 · Balıkesir',network:'Trugo',km:345,power:180,detour:0},{id:'akhisar-zes',name:'Oksijen O320 · Akhisar',network:'ZES',km:437,power:180,detour:0}]};
export function elevationAt(profile,km){let i=profile.findIndex(p=>p.km>=km);if(i<=0)return profile[Math.max(0,i)].elevation;const a=profile[i-1],b=profile[i];return a.elevation+(b.elevation-a.elevation)*(km-a.km)/(b.km-a.km);}
export function legEnergy(route,from,to,s){const points=[{km:from,elevation:elevationAt(route.profile,from)},...route.profile.filter(p=>p.km>from&&p.km<to),{km:to,elevation:elevationAt(route.profile,to)}];let energy=0,peak=0;for(let i=1;i<points.length;i++){energy+=segmentEnergy(points[i].km-points[i-1].km,points[i].elevation-points[i-1].elevation,s);peak=Math.max(peak,energy);}return {energy,peak};}
export function plan(route,s,excluded=[]){validate(s);const floor=s.reserve+s.buffer;const stations=route.stations.filter(p=>s.networks.includes(p.network)&&(!s.fastOnly||p.power>=50)&&!excluded.includes(p.id)).sort((a,b)=>a.km-b.km);const nodes=[{id:'start',km:0},...stations,{id:'end',km:route.distance}];const states=nodes.map(()=>new Map());states[0].set(s.battery,{soc:s.battery,cost:0,minutes:0,stops:[],trace:[{km:0,soc:s.battery}],score:0});let best=null;
for(let i=0;i<nodes.length-1;i++)for(const state of states[i].values())for(let j=i+1;j<nodes.length;j++){
const {energy,peak}=legEnergy(route,nodes[i].km,nodes[j].km,s);const detourEnergy=((nodes[i].detour||0)+(nodes[j].detour||0))*consumption(s)/100;const arrival=state.soc-(energy+detourEnergy)/s.capacity*100;if(state.soc-(peak+detourEnergy)/s.capacity*100<floor-1e-8)continue;
if(j===nodes.length-1){const candidate={...state,arrival,trace:[...state.trace,{km:route.distance,soc:arrival}],energy:(s.battery-arrival)/100*s.capacity+state.stops.reduce((v,x)=>v+x.kwh,0),distance:route.distance};if(!best||candidate.score<best.score)best=candidate;continue;}
for(let target=Math.max(5*Math.ceil((arrival+1)/5),5*Math.ceil(floor/5));target<=(s.chargeTarget??80);target+=5){const kwh=(target-arrival)/100*s.capacity;const minutes=chargeMinutes(arrival,target,nodes[j].power,s)+5+(nodes[j].detour||0)/40*120;const cost=kwh/.92*s.tariffs[nodes[j].network];const totalM=state.minutes+minutes,totalC=state.cost+cost;const score=s.priority==='fastest'?totalM:s.priority==='cheapest'?totalC:totalM+totalC/12;const old=states[j].get(target);if(!old||score<old.score)states[j].set(target,{soc:target,minutes:totalM,cost:totalC,score,stops:[...state.stops,{...nodes[j],arrival,target,kwh,minutes,cost}],trace:[...state.trace,{km:nodes[j].km,soc:arrival},{km:nodes[j].km,soc:target}]});}}
if(!best)throw Error('No plan meets your reserve with these stations and settings. Try a lower cruising speed, allow more networks, restore excluded stops, or add charging options.');return {...best,driveMinutes:route.source==='sample'?route.duration*130/s.speed:route.duration,consumption:consumption(s),payload:payload(s),floor};}
